function dataProcessor(csvData, includeHeaders = true) {
  try {
    const lines = csvData.trim().split('\n');
    const headers = includeHeaders ? lines.shift().split(',') : [];
    const rows = lines.map(line => line.split(','));

    const stats = {
      totalRows: rows.length,
      totalColumns: rows[0]?.length || 0,
      headers: headers,
      sampleData: rows.slice(0, 3),
      processedAt: new Date().toISOString()
    };

    return {
      success: true,
      result: stats,
      message: `Processed ${stats.totalRows} rows with ${stats.totalColumns} columns`
    };
  } catch (error) {
    return {
      success: false,
      error: error.message,
      message: 'Failed to process CSV data'
    };
  }
}
